let raw = $input.item.json.body || $input.item.json;
if (typeof raw === 'string') {
  try { raw = JSON.parse(raw); } catch (e) {}
}
return { json: { ...raw } };

const now = new Date();
const offset = now.getTimezoneOffset();
const madridOffset = 120; // CEST (UTC+2)
const diff = offset + madridOffset;
const local = new Date(now.getTime() + diff * 60000);
local.setDate(local.getDate() + 1);
const dateStr = local.getFullYear() + '-' +
  String(local.getMonth() + 1).padStart(2, '0') + '-' +
  String(local.getDate()).padStart(2, '0');
const result = [];
items.forEach(i => {
  const apt = i.json;
  const id = apt._id || apt.id;
  if (!id) return;
  apt.id = id;
  const email = apt.clientEmail || apt.client_email;
  const rawPhone = String(apt.clientPhone || apt.client_phone || '').replace(/\D/g, '');
  apt.clientEmail = email || '';
  apt.clientName = (apt.clientName || apt.client_name || '').trim() || 'Cliente';
  apt.clientPhone = rawPhone;
  apt.isPaid = apt.isPaid !== undefined ? apt.isPaid : apt.is_paid;
  if (apt.status === 'cancelled' || apt.status === 'noshow') return;
  if (apt.date !== dateStr) return;
  if (!rawPhone || rawPhone.length < 9) return;
  result.push({ json: apt });
});
return result;

const yesterdayStr = $now.minus({days: 1}).toISODate();
const result = [];
items.forEach(i => {
  const apt = i.json;
  if (apt.date === yesterdayStr) {
    const email = apt.clientEmail || apt.client_email;
    if (email) {
      apt.clientEmail = email;
      apt.clientName = apt.clientName || apt.client_name;
      apt.clientPhone = apt.clientPhone || apt.client_phone;
      apt.isPaid = apt.isPaid !== undefined ? apt.isPaid : apt.is_paid;
      result.push({ json: apt });
    }
  }
});
return result;
